    /**
     * Recursively searches for a file in a directory and its subdirectories.
     * 
     * @param directory The directory to search
     * @param fileName The name of the file to find
     * @param maxDepth The maximum depth to search
     * @return The path to the file, or null if not found
     * @throws IOException If an I/O error occurs
     */
    private static Path findFileInDirectory(Path directory, String fileName, int maxDepth) throws IOException {
        if (maxDepth <= 0) {
            return null;
        }
        
        try (var stream = Files.list(directory)) {
            for (Path path : (Iterable<Path>) stream::iterator) {
                if (Files.isDirectory(path)) {
                    Path result = findFileInDirectory(path, fileName, maxDepth - 1);
                    if (result != null) {
                        return result;
                    }
                } else if (path.getFileName().toString().equals(fileName)) {
                    return path;
                }
            }
        }
        
        return null;
    }
    
    /**
     * Abbreviates a string to a specified maximum length.
     * 
     * @param str The string to abbreviate
     * @param maxLength The maximum length
     * @return The abbreviated string
     */
    private static String abbreviate(String str, int maxLength) {
        if (str == null) {
            return "";
        }
        
        if (str.length() <= maxLength) {
            return str;
        }
        
        return str.substring(0, maxLength - 3) + "...";
    }
    
