     * 
     * @param javadoc The javadoc to extract tags from
     * @param tagName The name of the tag to extract
     * @return The value of the first tag with the specified name, or null if not found
     */
    private static String getTagValue(JavadocInfo javadoc, String tagName) {
        if (javadoc == null) {
            return null;
        }
        
        for (JavadocTag tag : javadoc.getTags()) {
            if (tag.getName().equals(tagName)) {
                return tag.getValue();
            }
        }
        
        return null;
    }
